import{_ as a,o,c as r,ag as t}from"./chunks/framework.CZxGLIO_.js";const b=JSON.parse('{"title":"故障排查","description":"定位 Rooster 地址、环境、任务状态、Cron、日志和恢复错误。","frontmatter":{"title":"故障排查","description":"定位 Rooster 地址、环境、任务状态、Cron、日志和恢复错误。"},"headers":[],"relativePath":"docs/rooster/troubleshooting/index.md","filePath":"docs/rooster/troubleshooting/index.md"}'),d={name:"docs/rooster/troubleshooting/index.md"};function c(n,e,i,l,h,s){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h1><p>排查时记录提交版本、启动方式、实际监听地址、数据目录、任务 ID 和执行 ID。任务名称不是唯一标识，Agent 或 API 操作应使用 ID。</p><h2 id="_9090-打不开或出现空任务列表" tabindex="-1">9090 打不开或出现空任务列表 <a class="header-anchor" href="#_9090-打不开或出现空任务列表" aria-label="Permalink to &quot;9090 打不开或出现空任务列表&quot;">​</a></h2><p>先看 <code>rooster ready</code> 日志。9090 被占用时会尝试后续 100 个端口，浏览器和 Agent 需要使用实际地址。执行 <code>curl --fail http://127.0.0.1:实际端口/api/health</code> 确认服务可达。</p><p>能打开但数据为空时，检查是否换了系统用户、<code>ROOSTER_DATA_DIR</code> 或启动方式。开发实例与日常实例应隔离，不能通过重复创建任务来掩盖目录错误。</p><h2 id="终端正常-任务却提示找不到程序" tabindex="-1">终端正常，任务却提示找不到程序 <a class="header-anchor" href="#终端正常-任务却提示找不到程序" aria-label="Permalink to &quot;终端正常，任务却提示找不到程序&quot;">​</a></h2><p>核对工作目录、程序绝对路径、参数拆分、Shell 模式与 PATH。Rooster 使用继承的登录环境缓存，托盘启动和当前终端不一定相同。将依赖明确写成任务环境变量，并使用可执行文件和目录的绝对路径。</p><p><code>exec</code> 不解析管道和重定向。需要 <code>|</code>、<code>&gt;</code> 或 shell 变量展开时选择 <code>shell</code>，并核对所选 shell 的语法。</p><h2 id="常驻任务反复重启-随后被停用" tabindex="-1">常驻任务反复重启，随后被停用 <a class="header-anchor" href="#常驻任务反复重启-随后被停用" aria-label="Permalink to &quot;常驻任务反复重启，随后被停用&quot;">​</a></h2><p>检查每次执行退出码、时长、错误和日志。运行不足默认 10 秒也会被守护器计为失败，连续失败默认达到 3 次后停用。<code>maxRetries=0</code> 使用默认值，不是无限重试。</p><p>如果命令本来就应快速结束，应使用定时任务；如果是服务启动失败，先手动验证命令，再启用守护。不要只增加重试次数而忽略启动错误。</p><h2 id="cron-没有触发或重复运行" tabindex="-1">Cron 没有触发或重复运行 <a class="header-anchor" href="#cron-没有触发或重复运行" aria-label="Permalink to &quot;Cron 没有触发或重复运行&quot;">​</a></h2><p>确认任务启用、表达式为五字段、进程时区符合预期，并查看未来五次触发时间。需要固定时区可使用 <code>CRON_TZ=Asia/Shanghai</code> 前缀。</p><p><code>skip</code> 会阻止与已有执行重叠，<code>parallel</code> 可能产生多个活动执行。运行状态只描述其中一个时，应查看完整历史。实例并发上限也可能拒绝新的执行。</p><h2 id="已停用-为什么命令还在运行" tabindex="-1">已停用，为什么命令还在运行 <a class="header-anchor" href="#已停用-为什么命令还在运行" aria-label="Permalink to &quot;已停用，为什么命令还在运行&quot;">​</a></h2><p>停用定时任务只取消后续触发，已有执行继续；需要停止对应执行 ID。常驻任务的手动执行也可能需要单独停止。停止请求是异步的，等待执行进入终态后再编辑或删除。</p><p>配置只读或返回 <code>422</code> 时，先确认任务已停用且没有活动执行。PUT 是完整替换，不支持变更 <code>kind</code>。</p><h2 id="api-成功返回但任务失败" tabindex="-1">API 成功返回但任务失败 <a class="header-anchor" href="#api-成功返回但任务失败" aria-label="Permalink to &quot;API 成功返回但任务失败&quot;">​</a></h2><p><code>202</code> 仅表示接受请求，不是成功完成。根据返回执行 ID 查询历史，查看 <code>status</code>、<code>exitCode</code> 和 <code>error</code>。超时限制触发时错误可为 <code>context deadline exceeded</code>。</p><p>创建或运行请求中断后先查询状态再重试，API 没有幂等键，盲目重试可能重复执行。</p><h2 id="日志缺失或磁盘持续增长" tabindex="-1">日志缺失或磁盘持续增长 <a class="header-anchor" href="#日志缺失或磁盘持续增长" aria-label="Permalink to &quot;日志缺失或磁盘持续增长&quot;">​</a></h2><p>日志接口仅展示当前文件最后 64 KiB。较早输出可能已轮转，使用归档接口读取。刚启动时文件可能尚未创建，恢复快照后日志也不会自动恢复。</p><p>20 MB 轮转和三个备份是单个日志的限制，不是全局容量限制。按 <a href="./../maintenance/">备份与日志</a> 预览并执行历史清理，检查响应中的错误。</p><h2 id="恢复命令拒绝目标目录" tabindex="-1">恢复命令拒绝目标目录 <a class="header-anchor" href="#恢复命令拒绝目标目录" aria-label="Permalink to &quot;恢复命令拒绝目标目录&quot;">​</a></h2><p>恢复只能写入尚不存在的新目录，不能覆盖旧实例。源应为 <code>/api/backup</code> 下载的独立快照，带非空 WAL 的在线数据库副本会被拒绝。完整步骤见 <a href="./../maintenance/">恢复指南</a>。</p><p>报告问题时附上脱敏配置、错误、任务与执行 ID 及复现步骤，移除环境变量中的密钥：<a href="https://github.com/leancodebox/rooster/issues" target="_blank" rel="noreferrer">Rooster Issues</a>。</p><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/README.md" target="_blank" rel="noreferrer">运行说明</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/httpapi/agent/references/api.md" target="_blank" rel="noreferrer">API 行为</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/roosterapp/restore.go" target="_blank" rel="noreferrer">恢复实现</a>。</p>',28)])])}const f=a(d,[["render",c]]);export{b as __pageData,f as default};
